9	// This file holds the constraint lifecycle operations: importing a draft
10	// definition from a JSON file, compiling a frozen version into a hashed
11	// artifact, and checking an input assignment against an artifact.
12	
13	// ImportConstraints reads a definition JSON file and stores it for one draft
14	// circuit version, replacing any previously imported definition as a whole.
15	//
16	// The version must exist and be a draft; a frozen version's definition can
17	// never be replaced (ErrFrozen). The file is parsed and fully validated
18	// against the version's declared counts before anything is committed, so a
19	// rejected import leaves the previous definition byte-for-byte in place.
20	// Unknown versions yield ErrNotFound; malformed or illegal definitions
21	// yield ErrInvalidArgument.
22	func (s *Store) ImportConstraints(name string, version int, path string) (Definition, error) {
23		if err := validateCircuitKey(name, version); err != nil {
24			return Definition{}, err
25		}
26		raw, err := os.ReadFile(path)
27		if err != nil {
28			return Definition{}, invalidf("cannot read constraint definition file %q: %v", path, err)
29		}
30	
31		var result Definition
32		err = s.withLock(func() (bool, error) {
33			circuit := findCircuit(s.data.Circuits, name, version)
34			if circuit == nil {
35				return false, notFoundf("circuit %q version %d does not exist", name, version)
36			}
37			if circuit.Frozen {
38				return false, frozenf("circuit %q version %d is frozen; its constraint definition cannot be replaced", name, version)
39			}
40			parsed, perr := parseDefinitionJSON(raw, circuit.PublicInputs, circuit.PrivateInputs, circuit.Constraints)
41			if perr != nil {
42				return false, perr
43			}
44			persisted := parsed.toPersist()
45			circuit.Definition = &persisted
46			result = parsed.toExport()
47			return true, nil
48		})
49		return result, err
50	}
51	
52	// GetDefinition returns the imported definition of one version. A version
53	// without one yields ErrDefinitionMissing, and an unknown version
54	// ErrNotFound.
55	func (s *Store) GetDefinition(name string, version int) (Definition, error) {
56		if err := validateCircuitKey(name, version); err != nil {
57			return Definition{}, err
58		}
59		var result Definition
60		err := s.withLockRead(func() error {
61			circuit := findCircuit(s.data.Circuits, name, version)
62			if circuit == nil {
63				return notFoundf("circuit %q version %d does not exist", name, version)
64			}
65			if circuit.Definition == nil {
66				return definitionMissingf("circuit %q version %d has no constraint definition", name, version)
67			}
68			parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
69			if perr != nil {
70				return corruptf("circuit %q v%d stored definition cannot be read: %v", name, version, perr)
71			}
72			result = parsed.toExport()
73			return nil
74		})
75		return result, err
76	}
77	
78	// CompileCircuit compiles a frozen circuit version into an artifact.
79	//
80	// Only frozen versions compile: unknown versions yield ErrNotFound, drafts
81	// ErrNotFrozen. A version whose counts were registered but which never had a
82	// definition imported yields ErrDefinitionMissing. Repeated compilation of
83	// the same version is idempotent and returns the identical artifact; other
84	// versions' artifacts are unaffected.
85	func (s *Store) CompileCircuit(name string, version int) (Artifact, error) {
86		if err := validateCircuitKey(name, version); err != nil {
87			return Artifact{}, err
88		}
89		var result Artifact
90		err := s.withLock(func() (bool, error) {
91			circuit := findCircuit(s.data.Circuits, name, version)
92			if circuit == nil {
93				return false, notFoundf("circuit %q version %d does not exist", name, version)
94			}
95			if !circuit.Frozen {
96				return false, notFrozenf("circuit %q version %d must be frozen before compilation", name, version)
97			}
98			if existing := findArtifact(s.data.Artifacts, name, version); existing != nil {
99				result = artifactFromPersist(*existing)
100				return false, nil
101			}
102			if circuit.Definition == nil {
103				return false, definitionMissingf("circuit %q version %d has only registered counts and no constraint definition; import one before freezing",
104					name, version)
105			}
106			parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
107			if perr != nil {
108				return false, corruptf("stored definition for %q v%d is unreadable: %v", name, version, perr)
109			}
110			if !parsed.compatibleWith(circuit.Constraints, circuit.PublicInputs, circuit.PrivateInputs) {
111				return false, corruptf("stored definition for %q v%d no longer matches its declared counts", name, version)
112			}
113			record := persistArtifact{
114				Name:        name,
115				Version:     version,
116				Modulus:     parsed.modulus,
117				Constraints: len(parsed.constraints),
118				Hash:        artifactHash(name, version, parsed),
119			}
120			s.data.Artifacts = append(s.data.Artifacts, record)
121			result = artifactFromPersist(record)
122			return true, nil
123		})
124		return result, err
125	}
126	
127	// GetArtifact returns the compiled artifact for one version. A version
128	// without one yields ErrArtifactMissing, and an unknown version ErrNotFound.
129	func (s *Store) GetArtifact(name string, version int) (Artifact, error) {
130		if err := validateCircuitKey(name, version); err != nil {
131			return Artifact{}, err
132		}
133		var result Artifact
134		err := s.withLockRead(func() error {
135			circuit := findCircuit(s.data.Circuits, name, version)
136			if circuit == nil {
137				return notFoundf("circuit %q version %d does not exist", name, version)
138			}
139			existing := findArtifact(s.data.Artifacts, name, version)
140			if existing == nil {
141				return artifactMissingf("circuit %q version %d has no compiled artifact", name, version)
142			}
143			result = artifactFromPersist(*existing)
144			return nil
145		})
146		return result, err
147	}
148	
149	// CheckInput tests one input assignment against the named version's
150	// compiled artifact. hash must equal that artifact's hash, binding the check
151	// to an explicit compilation result.
152	//
153	// Gating errors are reported distinctly: unknown version ErrNotFound,
154	// unfrozen version ErrNotFrozen, no compiled artifact ErrArtifactMissing and
155	// a hash that does not belong to the target version ErrArtifactMismatch. A
156	// malformed witness (wrong lengths or illegal values; a nil slice stands for
157	// an empty one) yields ErrInvalidInput and never reaches evaluation.
158	//
159	// On success the verdict reports satisfaction, the bound artifact hash and,
160	// when unsatisfied, the 1-based index of the first failing constraint. No
161	// private input value is included in the result and no proof job is created.
162	//
163	// CheckInputFile applies exactly the same gating, binding and evaluation;
164	// only the witness representation differs.
165	func (s *Store) CheckInput(name string, version int, hash string, witness Witness) (CheckResult, error) {
166		if err := validateCheckRequest(name, version, hash); err != nil {
167			return CheckResult{}, err
168		}
169		var result CheckResult
170		err := s.withLockRead(func() error {
171			def, boundHash, gerr := s.boundCheckDefinition(name, version, hash)
172			if gerr != nil {
173				return gerr
174			}
175			if err := validateWitness(witness, def.public, def.private); err != nil {
176				return err
177			}
178			result = evaluateCheck(def, witness, boundHash)
179			return nil
180		})
181		return result, err
182	}
183	
184	// CheckInputFile is CheckInput with the witness read from a JSON file. It
185	// shares every gating, binding and evaluation rule with CheckInput; the only
186	// differences are how the witness is supplied (a strict JSON document that
187	// must explicitly contain both string arrays, even when empty) and that an
188	// unreadable or malformed file is reported as an input format error.
189	//
190	// The file is read first, so a missing or unreadable file keeps its read
191	// error; but once the file can be read, all binding gating still runs
192	// against the live store — an unknown version, a draft, a missing artifact
193	// or a wrong hash is reported before any complaint about the file's
194	// contents.
195	func (s *Store) CheckInputFile(name string, version int, hash, path string) (CheckResult, error) {
196		if err := validateCheckRequest(name, version, hash); err != nil {
197			return CheckResult{}, err
198		}
199		raw, err := os.ReadFile(path)
200		if err != nil {
201			return CheckResult{}, inputFormatf("cannot read input file %q: %v", path, err)
202		}
203		var result CheckResult
204		err = s.withLockRead(func() error {
205			def, boundHash, gerr := s.boundCheckDefinition(name, version, hash)
206			if gerr != nil {
207				return gerr
208			}
209			witness, werr := parseWitness(raw, def.public, def.private)
210			if werr != nil {
211				return werr
212			}
213			result = evaluateCheck(def, witness, boundHash)
214			return nil
215		})
216		return result, err
217	}
218	
219	// validateCheckRequest covers the request-shape checks common to both
220	// entry points: an explicit non-whitespace circuit key and a non-empty
221	// artifact hash.
222	func validateCheckRequest(name string, version int, hash string) error {
223		if err := validateCircuitKey(name, version); err != nil {
224			return err
225		}
226		if hash == "" {
227			return invalidf("an artifact hash is required to check inputs")
228		}
229		return nil
230	}
231	
232	// boundCheckDefinition resolves and verifies everything a check is bound
233	// to, in the required order: the version must exist and be frozen, its
234	// compiled artifact must exist, the supplied hash must equal that
235	// artifact's hash (artifacts of other names or versions never qualify), and
236	// the stored definition behind the artifact must be readable. It returns
237	// the canonical definition and the bound artifact hash.
238	//
239	// Callers must hold the store read lock.
240	func (s *Store) boundCheckDefinition(name string, version int, hash string) (*canonicalDefinition, string, error) {
241		circuit := findCircuit(s.data.Circuits, name, version)
242		if circuit == nil {
243			return nil, "", notFoundf("circuit %q version %d does not exist", name, version)
244		}
245		if !circuit.Frozen {
246			return nil, "", notFrozenf("circuit %q version %d must be frozen before inputs can be checked", name, version)
247		}
248		artifact := findArtifact(s.data.Artifacts, name, version)
249		if artifact == nil {
250			return nil, "", artifactMissingf("circuit %q version %d has no compiled artifact", name, version)
251		}
252		if artifact.Hash != hash {
253			return nil, "", artifactMismatchf("artifact hash %q does not belong to circuit %q version %d (bound hash %q)",
254				hash, name, version, artifact.Hash)
255		}
256		if circuit.Definition == nil {
257			return nil, "", corruptf("artifact for %q v%d exists but its definition is missing", name, version)
258		}
259		parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
260		if perr != nil {
261			return nil, "", corruptf("stored definition for %q v%d is unreadable: %v", name, version, perr)
262		}
263		return parsed, artifact.Hash, nil
264	}
265	
266	// evaluateCheck runs the one shared verdict: the 1-based index of the first
267	// failing constraint, or zero when every constraint holds.
268	func evaluateCheck(def *canonicalDefinition, witness Witness, hash string) CheckResult {
269		failure := def.evaluate(witness)
270		return CheckResult{Satisfied: failure == 0, Hash: hash, FirstFailure: failure}
271	}
272	
273	// validateWitness applies the witness grammar and layout rules for an
274	// in-API call and tags every rejection as an input format error.
275	func validateWitness(w Witness, public, private int) error {
276		if _, err := witnessFromArrays(w.Public, w.Private, public, private); err != nil {
277			var se StoreError
278			if errors.As(err, &se) {
279				return StoreError{Kind: ErrInvalidInput.Kind, Detail: se.Detail}
280			}
281			return inputFormatf("%v", err)
282		}
283		return nil
284	}
285	
286	// --- lookup / mapping helpers ---------------------------------------------
