528	// Gating precedence is identical at both entry points, and a readable but
529	// malformed file never masks a failed binding: business errors are reported
530	// before the file's contents are parsed.
531	func TestCheckInputFileGatingPrecedence(t *testing.T) {
532		s := openTestStore(t)
533		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
534		s.FreezeCircuit("c", 1)
535		a, _ := s.CompileCircuit("c", 1)
536		badDoc := writeTempJSON(t, `{not json`)
537	
538		if _, err := s.CreateCircuit(Circuit{Name: "d", Version: 1, Constraints: 1, Description: "d"}); err != nil {
539			t.Fatal(err)
540		}
541	
542		if _, err := s.CheckInputFile("ghost", 1, a.Hash, badDoc); !errors.Is(err, ErrNotFound) {
543			t.Fatalf("unknown version beats malformed file: %v", err)
544		}
545		if _, err := s.CheckInputFile("d", 1, a.Hash, badDoc); !errors.Is(err, ErrNotFrozen) {
546			t.Fatalf("unfrozen beats malformed file: %v", err)
547		}
548		s.FreezeCircuit("d", 1)
549		if _, err := s.CheckInputFile("d", 1, a.Hash, badDoc); !errors.Is(err, ErrArtifactMissing) {
550			t.Fatalf("missing artifact beats malformed file: %v", err)
551		}
552		if _, err := s.CheckInputFile("c", 1, a.Hash+"00", badDoc); !errors.Is(err, ErrArtifactMismatch) {
553			t.Fatalf("hash mismatch beats malformed file: %v", err)
554		}
555		// Direct entry shares the same order.
556		if _, err := s.CheckInput("ghost", 1, a.Hash, Witness{}); !errors.Is(err, ErrNotFound) {
557			t.Fatalf("direct unknown version: %v", err)
558		}
559		if _, err := s.CheckInput("c", 1, a.Hash+"00", Witness{Public: []string{"2"}, Private: []string{"3"}}); !errors.Is(err, ErrArtifactMismatch) {
560			t.Fatalf("direct wrong hash: %v", err)
561		}
562	
563		// A missing/unreadable file keeps the read error; binding validation
564		// never rewrites it as another cause.
565		if _, err := s.CheckInputFile("c", 1, a.Hash, filepath.Join(t.TempDir(), "missing.json")); !errors.Is(err, ErrInvalidInput) {
566			t.Fatalf("unreadable file must be an input format error, got %v", err)
567		}
568	}
