	// A count change that keeps the definition legal is accepted.
	if _, err := s.UpdateCircuit(Circuit{Name: "c", Version: 1, Constraints: 1,
		PublicInputs: 2, PrivateInputs: 3, Description: "wider"}); err != nil {
