656	func parseWitnessDocument(raw []byte, public, private int) (Witness, error) {
657		members, err := strictObject(raw, []string{"public", "private"}, "input")
658		if err != nil {
659			return Witness{}, err
660		}
661		publicRaw, err := requireMember(members, "public", "input")
662		if err != nil {
