666		if err != nil {
667			return Witness{}, err
668		}
669		parseArray := func(raw json.RawMessage, which string) ([]string, error) {
670			if string(bytes.TrimSpace(raw)) == "null" {
671				return nil, invalidf("input field %q must be an array", which)
672			}
673			var values []string
674			if err := json.Unmarshal(raw, &values); err != nil {
675				return nil, invalidf("input field %q must be an array of decimal strings: %v", which, err)
676			}
677			return values, nil
678		}
679		pubValues, err := parseArray(publicRaw, "public")
680		if err != nil {
681			return Witness{}, err
682		}
683		privValues, err := parseArray(privateRaw, "private")
684		if err != nil {
685			return Witness{}, err
686		}
687		return witnessFromArrays(pubValues, privValues, public, private)
688	}
689	
690	// witnessFromArrays applies the single witness grammar and layout rule
691	// shared by both check entry points: each group must contain exactly the
692	// declared number of decimal strings. A nil slice is accepted wherever an
693	// empty one would be (an in-API witness declaring zero inputs); unlike the
694	// JSON entry point nothing here distinguishes "omitted" from "empty".
695	// Values are never echoed for the private group.
696	func witnessFromArrays(pubValues, privValues []string, public, private int) (Witness, error) {
697		if len(pubValues) != public {
698			return Witness{}, invalidf("public input length mismatch: got %d values, version declares %d", len(pubValues), public)
699		}
700		if len(privValues) != private {
701			return Witness{}, invalidf("private input length mismatch: got %d values, version declares %d", len(privValues), private)
702		}
703		if err := validateWitnessValues(pubValues, "public", true); err != nil {
704			return Witness{}, err
705		}
706		if err := validateWitnessValues(privValues, "private", false); err != nil {
707			return Witness{}, err
708		}
709		return Witness{Public: pubValues, Private: privValues}, nil
710	}
