712	// validateWitnessValues checks that every entry is an arbitrarily long
713	// signed decimal string. Private values are deliberately not echoed back.
714	func validateWitnessValues(values []string, which string, echo bool) error {
715		for i, v := range values {
716			if _, err := parseBigSignedDecimal(v); err != nil {
717				if echo {
718					return invalidf("%s input #%d value %q is not a decimal integer: %v", which, i+1, v, err)
719				}
720				return invalidf("%s input #%d value is not a decimal integer: %v", which, i+1, err)
721			}
722		}
723		return nil
724	}
