726	// evaluate checks every constraint against the witness and returns the
727	// 1-based index of the first failure, or 0 when all hold.
728	func (d *canonicalDefinition) evaluate(w Witness) int {
729		p := d.modulus
730		// Wire layout: 0 = 1, then public inputs, then private inputs.
731		values := make([]int64, 1+d.public+d.private)
732		values[0] = 1
733		bigP := big.NewInt(p)
734		for i, s := range w.Public {
735			n, _ := parseBigSignedDecimal(s)
736			n.Mod(n, bigP)
737			values[1+i] = n.Int64()
738		}
739		for i, s := range w.Private {
740			n, _ := parseBigSignedDecimal(s)
741			n.Mod(n, bigP)
742			values[1+d.public+i] = n.Int64()
743		}
744		combo := func(terms []parsedTerm) int64 {
745			var sum int64
746			for _, t := range terms {
747				// sum < p and the product < (p-1)^2 < 2^62, so this add never
748				// overflows int64.
749				sum = modInt64(sum+t.value*values[t.wire], p)
750			}
751			return sum
752		}
753		for i, con := range d.constraints {
754			av := combo(con.a)
755			bv := combo(con.b)
756			cv := combo(con.c)
757			if modInt64(av*bv, p) != cv {
758				return i + 1
759			}
760		}
761		return 0
762	}
