func TestScratchNoLeak(t *testing.T) {
	// Marker bytes that must never appear in any diagnostic for private content.
	docs := []struct {
		name        string
		doc         string
		pub, priv   int
		mustNotHave []string
	}{
		{"illegal char", `{"public":["2"],"private":["123Q"]}`, 1, 1, []string{"Q", "123"}},
		{"empty string", `{"public":["2"],"private":[""]}`, 1, 1, nil},
		{"sign only", `{"public":["2"],"private":["-"]}`, 1, 1, nil},
		{"dup key in obj elem", `{"public":["2"],"private":[{"k":1,"k":2}]}`, 1, 1, []string{`"k"`, "duplicate", "k"}},
		{"number elem", `{"public":["2"],"private":[7]}`, 1, 1, []string{"7"}},
		{"bool elem", `{"public":["2"],"private":[true]}`, 1, 1, []string{"true"}},
		{"null elem", `{"public":["2"],"private":[null]}`, 1, 1, nil},
		{"nested array elem", `{"public":["2"],"private":[["x"]]}`, 1, 1, []string{"x"}},
		{"syntax err in private", `{"public":["2"],"private":["a" "b"]}`, 1, 1, []string{"a", "b"}},
		{"truncated private", `{"public":["2"],"private":["3"`, 1, 1, []string{"3"}},
		{"garbage", `{bad`, 0, 0, []string{"bad"}},
		{"bad after object", `{"public":[],"private":[]} @@@`, 0, 0, []string{"@"}},
	}
	for _, tc := range docs {
		t.Run(tc.name, func(t *testing.T) {
			_, err := parseWitness([]byte(tc.doc), tc.pub, tc.priv)
			if err == nil {
				t.Fatalf("expected rejection")
			}
			if !errors.Is(err, ErrInvalidInput) {
				t.Fatalf("want ErrInvalidInput, got %v", err)
			}
			msg := err.Error()
			t.Logf("%-22s -> %s", tc.name, msg)
			for _, m := range tc.mustNotHave {
				if containsStr(msg, m) {
					t.Errorf("diagnostic leaks %q: %s", m, msg)
				}
			}
		})
	}
}

func containsStr(s, sub string) bool {
	return len(sub) > 0 && indexOf(s, sub) >= 0
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}

