	t.Helper()
	s := openTestStore(t)
	seedDraftWithDef(t, s, name, 1, pub, priv, validDef)
	if _, err := s.FreezeCircuit(name, 1); err != nil {
		t.Fatal(err)
	}
	a, err := s.CompileCircuit(name, 1)
	if err != nil {
